function normalizeSymbol(symbol) {
  return String(symbol ?? '')
    .trim()
    .toUpperCase();
}

/** Strip time-varying financial fact labels if present in older data. */
const BLOCKED_FACT_LABELS = /^(mkt\.?\s*cap|market\s*cap|fy\d*\s*|ops?\s*rev|revenue|pat|eps|pe\b|pb\b)/i;

export function sanitizeBriefFacts(facts) {
  return (facts ?? []).filter((fact) => {
    const label = String(fact?.label ?? '');
    return label && !BLOCKED_FACT_LABELS.test(label);
  });
}

function withResolvedLogo(brief) {
  if (!brief) return null;
  const logoUrl =
    resolveAssetLogoUrl({
      logoIconUrl: brief.logoUrl,
      assetType: 'stock',
      assetKey: brief.symbol,
      variant: LOGO_VARIANT_DETAIL,
    }) || brief.logoUrl;
  return {
    ...brief,
    logoUrl,
    facts: sanitizeBriefFacts(brief.facts),
  };
}

export async function loadCompanyBriefIndex() {
  if (!indexPromise) {
    indexPromise = fetch(INDEX_URL)
      .then((res) => {
        if (!res.ok) throw new Error(`Failed to load company brief index (${res.status})`);
        return res.json();
      })
      .catch((err) => {
        indexPromise = null;
        throw err;
      });
  }
  return indexPromise;
}

async function loadShard(symbol) {
  const key = normalizeSymbol(symbol);
  const url = shardUrl(key);
  if (!shardCache.has(url)) {
    shardCache.set(
      url,
      fetch(url)
        .then((res) => {
          if (!res.ok) throw new Error(`Failed to load brief shard (${res.status})`);
          return res.json();
        })
        .catch((err) => {
          shardCache.delete(url);
          throw err;
        })
    );
  }
  return shardCache.get(url);
}

export async function getCompanyBrief(symbol) {
  const key = normalizeSymbol(symbol);
  if (!key) return null;
  if (CURATED_BRIEFS[key]) return withResolvedLogo(CURATED_BRIEFS[key]);

  try {
    const shard = await loadShard(key);
    return withResolvedLogo(shard?.[key] ?? null);
  } catch {
    return null;
  }
}

export function searchCompanyBriefIndex(items, query, limit = 12) {
  const q = String(query ?? '')
    .trim()
    .toUpperCase();
  if (q.length < 1 || !items?.length) return [];
  const next = [];
  for (const item of items) {
    const symbol = String(item.symbol ?? '').toUpperCase();
    const name = String(item.name ?? item.legalName ?? '').toUpperCase();
    if (symbol.includes(q) || name.includes(q)) {
      next.push(item);
      if (next.length >= limit) break;
    }
  }
  return next;
}

/** @deprecated use getCompanyBrief — kept for sync curated list previews */
export function listCuratedCompanyBriefs() {
  return Object.values(CURATED_BRIEFS).map(withResolvedLogo);
}
